input.command:
bun -e '
const cli = "src/cli.ts";
const cases = [
  ["empty", { tasks: [] }, 0, { order: [], layers: [], earliest: {}, totalDuration: 0, criticalPath: [] }],
  ["schedule", { tasks: [{id:"deploy",duration:1,dependsOn:["build","test"]},{id:"lint",duration:2},{id:"build",duration:3,dependsOn:["lint"]},{id:"test",duration:4,dependsOn:["lint"]}] }, 0, { order:["lint","build","test","deploy"], layers:[["lint"],["build","test"],["deploy"]], earliest:{lint:{start:0,finish:2},build:{start:2,finish:5},test:{start:2,finish:6},deploy:{start:6,finish:7}}, totalDuration:7, criticalPath:["lint","test","deploy"] }],
  ["zero-tie", { tasks: [{id:"root",duration:0},{id:"a",duration:2,dependsOn:["root"]},{id:"b",duration:2},{id:"end",duration:1,dependsOn:["a","b"]}] }, 0, { order:["b","root","a","end"], layers:[["b","root"],["a"],["end"]], earliest:{b:{start:0,finish:2},root:{start:0,finish:0},a:{start:0,finish:2},end:{start:2,finish:3}}, totalDuration:3, criticalPath:["root","a","end"] }],
  ["cycle", { tasks: [{id:"b",duration:1,dependsOn:["a"]},{id:"a",duration:1,dependsOn:["b"]}] }, 1, "Cycle detected: a -> b -> a"],
  ["bad-schema", { tasks: [{id:"a",duration:-1}] }, 1, "duration must be a finite non-negative number"],
  ["unknown-dependency", { tasks: [{id:"a",duration:1,dependsOn:["missing"]}] }, 1, "unknown dependency"]
];
for (const [name, value, status, expected] of cases) {
  const path = `/tmp/dependency-planner-${name}.json`;
  await Bun.write(path, JSON.stringify(value));
  const result = Bun.spawnSync(["bun", "run", cli, "plan", path]);
  if (result.exitCode !== status) throw new Error(`${name}: expected exit ${status}, got ${result.exitCode}`);
  const output = new TextDecoder().decode(status === 0 ? result.stdout : result.stderr).trim();
  if (typeof expected === "string") {
    if (!output.includes(expected)) throw new Error(`${name}: unexpected error ${output}`);
  } else if (output !== JSON.stringify(expected)) throw new Error(`${name}: expected ${JSON.stringify(expected)}, got ${output}`);
}
for (const args of [["unknown"], ["plan", "-flag"]]) {
  const result = Bun.spawnSync(["bun", "run", cli, ...args]);
  if (result.exitCode === 0 || !new TextDecoder().decode(result.stderr).includes("Usage:")) throw new Error(`args ${args}: expected usage failure`);
}
console.log("all comprehensive CLI tests passed");
'

